"""Cuaderno del estudiante, 5.º básico Lenguaje y Comunicación, OA 02 (estrategias de comprensión lectora).

Textos originales y breves; cada ejercicio trae el texto que necesita.
"""
from __future__ import annotations

from student_content_le5_a import E, L, n_words
from student_lessons import arith

OA2 = "LE05 OA 02"

BALLENAS = "Las ballenas jorobadas viajan miles de kilómetros cada año para tener a sus crías en aguas cálidas. Allí hay poco alimento, así que pasan meses comiendo muy poco y viven de la grasa que guardaron."
FARO = "El faro de la isla guía a los barcos en la noche. Su luz gira y barre el mar. Los marinos, al verla, saben que la costa está cerca, aunque la niebla les impida ver las rocas."
CONDOR = "Los cóndores usan las corrientes de aire caliente para elevarse sin aletear. Así ahorran energía y pueden recorrer grandes distancias buscando alimento. Suelen vivir en la cordillera, donde hay rocas altas para descansar."
FERIA = "La Feria del Libro se hará en la plaza el sábado 12, de 10 a 18 horas. Habrá cuentacuentos para niños y un taller de poesía a las 15 horas. La entrada es gratuita. Los organizadores piden llevar una bolsa para guardar los libros."
SEMILLA = "Para crecer, una semilla necesita agua, tierra y luz. En el desierto, muchas semillas esperan años bajo la arena hasta que cae una lluvia."
AGUA = "El agua del mar y de los ríos se calienta con el sol y sube al aire como vapor. En lo alto, el vapor se enfría y forma nubes. Cuando las gotas de las nubes pesan mucho, caen como lluvia o nieve y vuelven a los ríos y al mar."
GLACIAR = "Los glaciares son enormes masas de hielo que se mueven muy despacio. Se forman en lugares donde cae más nieve de la que se derrite. Con el tiempo, la nieve se aprieta y se convierte en hielo."

L(OA2, 1,
  "Este cuaderno, lápiz y el texto escrito en esta clase.",
  "Aprenderé a relacionar lo que leo con mis experiencias y conocimientos previos para comprender mejor un texto.",
  ["Leo textos breves con precisión.", "Sé que un texto informativo entrega datos."],
  ["Comprender un texto no es solo pasar los ojos por las palabras. Un lector activo relaciona lo que lee con lo que ya sabe. Un conocimiento previo es algo que aprendiste antes, como que los osos guardan grasa para el invierno. Una experiencia es algo que viviste, como ver la ropa secarse al sol.",
   "Estas relaciones sirven cuando ayudan a entender el texto. Si lees que las ballenas viven de la grasa guardada y recuerdas que otros animales también guardan energía, la idea se vuelve más fácil de entender. Pero pensar en algo sin relación, como tu color favorito, no ayuda.",
   "Antes de leer, pregúntate: ¿qué sé de este tema? ¿Qué he vivido que se le parece? Durante la lectura, compara lo nuevo con lo que ya sabías. Si algo de lo que creías no coincide con el texto, corrige tu idea."],
  [("conocimiento previo", "lo que ya sabes de un tema antes de leer"), ("experiencia", "algo que viviste"), ("relacionar", "encontrar qué tiene en común una cosa con otra"), ("lector activo", "quien piensa y se hace preguntas mientras lee")],
  [("Una relación útil", f"Lees: «{BALLENAS}» ¿Qué conocimiento ayuda a entender «viven de la grasa que guardaron»?", ["Pienso en otros animales que pasan meses sin comer mucho.", "Recuerdo que los osos guardan grasa para el invierno.", "Así entiendo que la grasa es una reserva de energía."], "Los osos guardan grasa; la grasa es una reserva de energía"),
   ("Una relación que no ayuda", "Al leer sobre ballenas piensas «mi color favorito es el verde». ¿Te ayuda a comprender el texto?", ["Reviso si el color tiene que ver con las ballenas.", "El texto no habla de colores.", "No aporta a la comprensión."], "No, no se relaciona con el texto")],
  [("Pensar en cualquier cosa mientras se lee.", "Se cree que relacionar es recordar lo que sea.", "Elige recuerdos que expliquen algo del texto."), ("Mantener una idea previa aunque el texto diga otra cosa.", "Cuesta cambiar lo que uno creía.", "Si no coincide, corrige tu idea con lo que dice el texto.")],
  ([E("Antes de leer sobre ballenas recuerdas que viven en el mar. ¿Es un conocimiento previo o una experiencia?", "Conocimiento previo", "Es algo que ya sabes del tema."),
    E("Recuerdas el día en que viste el mar en vacaciones. ¿Es un conocimiento previo o una experiencia?", "Una experiencia", "Es algo que tú viviste."),
    E("¿Relacionar el texto con lo que sabes sirve para entender mejor o para leer más rápido?", "Para entender mejor", "Las conexiones ayudan a dar sentido a lo nuevo.")],
   [E("¿Qué conocimiento ayuda a entender «viven de la grasa que guardaron»: (a) los animales guardan energía en su cuerpo o (b) las ballenas tienen aletas?", "(a)", "La grasa guardada funciona como reserva de energía."),
    E("Un niño dice «Esto me recuerda a las aves, que también viajan lejos cada año». ¿Con qué relaciona el texto?", "Con otros animales que viajan", "Compara la migración de las ballenas con la de las aves."),
    E("¿Qué conexión es más útil para el texto de las ballenas: (a) «los osos guardan grasa para el invierno» o (b) «me gusta el color azul»?", "(a)", "Se parece a lo que el texto explica; la otra no.")],
   [E("Lees: «El charqui es carne secada al aire. Sirve para conservar la comida mucho tiempo.» Si sabes que la comida húmeda se echa a perder, ¿para qué crees que se seca la carne: (a) para que se conserve o (b) para que sepa dulce?", "(a)", "Sin humedad la comida se echa a perder más lentamente."),
    E("Lees: «El agua de un charco desaparece poco a poco bajo el sol.» ¿Qué experiencia ayuda a entenderlo: la ropa mojada que se seca al sol o jugar a la pelota?", "La ropa mojada que se seca al sol", "Es una situación parecida: el sol seca el agua."),
    E("¿Qué oración muestra un conocimiento previo: (a) «Sé que el sol sale por el este» o (b) «Hoy no tengo sueño»?", "(a)", "Es algo que se sabe sobre el tema.")],
   [E("Ana relaciona el texto de las ballenas con «los osos guardan grasa». Beto, con «hoy fui al dentista». ¿Quién comprenderá mejor que las ballenas viven de su grasa?", "Ana", "Su conexión se parece a lo que explica el texto."),
    E("Una lectora relaciona el texto con algo que no tiene que ver. ¿Eso ayuda a comprender?", "No", "Relacionar sirve solo si aclara algo del texto.")],
   [E("Lees: «" + SEMILLA + "» ¿Qué conocimiento previo explica por qué esperan la lluvia?", "Las semillas necesitan agua para crecer", "El texto lo dice y lo sabes de plantas."),
    E(SEMILLA + " Ana conectó el texto de las semillas con «mi planta necesita riego». Marcos, con «mi tío vive en el norte». ¿Cuál conexión ayuda a comprender mejor?", "La de Ana", "Habla de que las plantas necesitan agua, igual que el texto.")]),
  [E("En Ciencias leerás sobre los volcanes. Antes de leer, ¿qué te conviene recordar: lo que sabes de los volcanes o lo que cenaste ayer?", "Lo que sabes de los volcanes", "Activar lo que sabes del tema ayuda a comprender.")],
  [E("En Lenguaje: ¿Qué es un conocimiento previo?", "Lo que ya sé sobre un tema", "Se aprendió antes de leer."),
   E("En Lenguaje: ¿Qué es una experiencia?", "Algo que viví", "Es una vivencia propia."),
   E("Si una idea previa no coincide con el texto, ¿qué haces?", "Corrijo mi idea con lo que dice el texto", "El texto aporta información nueva.")],
  (f"Lee este texto: «{BALLENAS}» Escribe dos relaciones: una con un conocimiento previo y otra con una experiencia tuya. Explica en una oración cómo cada una te ayuda a entender el texto.", "Conocimiento: sé que los osos guardan grasa para el invierno; me ayuda a entender que la grasa es una reserva. Experiencia: una vez caminé todo un día y terminé muy cansada; entiendo que un viaje largo gasta mucha energía.", ["escribe una relación con un conocimiento previo", "escribe una relación con una experiencia", "explica cómo cada una ayuda a entender"], ["dos relaciones escritas", "explicación breve"], ["relacionar con algo que no aclara el texto", "no explicar la relación"], "Cambia la conexión por otra y pregúntate si de verdad aclara algo del texto."),
  "Antes de leer un texto de otra asignatura, anota tres cosas que ya sabes del tema.",
  "Elige un texto breve y escribe una conexión útil y otra que no ayude, explicando la diferencia.")

L(OA2, 2,
  "Este cuaderno, lápiz y el texto escrito en esta clase.",
  "Aprenderé a darme cuenta de cuándo no comprendo lo que leo y a releer de manera inteligente para aclarar mi duda.",
  ["Relaciono lo que leo con lo que sé.", "Sé qué es una oración."],
  ["A veces seguimos leyendo aunque no entendimos. Un buen lector se da cuenta de eso. Hay señales de que no comprendiste: no puedes contar con tus palabras lo que acabas de leer, no sabes quién hace algo en una oración o hay una palabra que no conoces.",
   "Cuando pasa eso, releer ayuda. Pero no se trata de repetir sin pensar. Relee la oración que no entendiste, y también la anterior y la siguiente: allí suelen estar las pistas. Léela más despacio, fíjate en palabras que unen ideas, como «aunque» o «porque», y pregúntate quién hace qué.",
   "Después de releer, cuenta con tus palabras lo que entendiste. Si ya puedes explicarlo, sigue leyendo. Si no, prueba otra estrategia, como buscar el significado de la palabra por las pistas del texto o preguntar a otra persona."],
  [("releer", "volver a leer una parte para entenderla mejor"), ("pista", "dato del texto que ayuda a entender algo"), ("contar con tus palabras", "explicar lo leído sin copiar el texto"), ("conector", "palabra que une ideas, como «porque» o «aunque»")],
  [("Releer buscando pistas", f"Lees: «{FARO}» No entiendes «barre el mar». ¿Qué haces?", ["Releo la oración y la anterior.", "La anterior dice que la luz «gira».", "Entiendo que la luz pasa girando sobre el mar, como una escoba sobre el piso."], "Releo con pistas: la luz gira y pasa por todo el mar"),
   ("Entender «aunque»", "«Aunque la lluvia cesó, el río siguió creciendo.» ¿Qué muestra «aunque»?", ["Veo dos hechos: la lluvia cesó, el río creció.", "«Aunque» indica que el segundo hecho es inesperado.", "El río crece a pesar de que no llueve."], "Algo ocurre a pesar de otro hecho")],
  [("Seguir leyendo cuando algo no se entendió.", "Se espera que más adelante se aclare solo.", "Detente y relee antes de continuar."), ("Releer palabra por palabra sin pensar.", "Se cree que repetir basta.", "Relee con una pregunta: ¿quién hace qué?")],
  ([E("No puedes explicar con tus palabras lo que acabas de leer. ¿Qué haces: seguir o releer?", "Releer", "Esa es la señal de que falta comprender."),
    E("¿Qué es una señal de que no comprendiste: (a) no sabes quién hace algo en la oración o (b) terminaste rápido?", "(a)", "No saber quién hace algo muestra que falta comprensión."),
    E("Al leer, volver a una parte para leerla otra vez y entenderla mejor se llama...", "Releer", "Es la acción de leer de nuevo una parte.")],
   [E(FARO + " Según el texto del faro, ¿para qué sirve la luz del faro?", "Guía a los barcos en la noche", "El texto lo dice al comienzo."),
    E("No sabes qué significa «barre» en «Su luz gira y barre el mar». ¿Qué te conviene: seguir adelante o releer la oración y las cercanas buscando pistas?", "Releer buscando pistas", "La oración anterior y la siguiente ayudan."),
    E("¿Releer es lo mismo que leer más rápido?", "No", "Releer es volver a una parte para entenderla.")],
   [E(FARO + " «Aunque la niebla les impida ver las rocas». ¿Quiénes no pueden ver las rocas?", "Los marinos", "Es lo que dice la oración completa."),
    E(FARO + " Según el texto del faro, ¿qué saben los marinos al ver la luz?", "Que la costa está cerca", "Esa es la información que la luz entrega."),
    E(FARO + " ¿Cuántas oraciones tiene el texto del faro?", "3", "Terminan con punto en «noche», «mar» y «rocas».")],
   [E("Leíste «la niebla les impida ver las rocas» y pensaste que la niebla ayudaba a ver. Al releer, ¿qué palabra te hace corregir tu idea?", "impida", "«Impida» indica que no se puede ver."),
    E("Lees: «El zorro no cruzó el puente. Estaba roto.» No sabes qué estaba roto. ¿Qué haces: releer la oración anterior para ver a qué se refiere «Estaba» o seguir sin pensar?", "Releer la oración anterior", "La oración anterior dice que se trata del puente: el puente estaba roto.")],
   [E("«Aunque la lluvia cesó, el río siguió creciendo porque la nieve de la cordillera se derretía.» ¿Por qué siguió creciendo el río?", "Porque la nieve de la cordillera se derretía", "«Porque» introduce la causa."),
    E("En la oración anterior, ¿qué palabra muestra que el río creció a pesar de que dejó de llover?", "aunque", "«Aunque» une dos hechos que parecen opuestos.")]),
  [E("Un aviso dice: «Quienes no hayan entregado la autorización no podrán salir de paseo.» ¿Puede salir quien no la entregó?", "No", "El aviso dice que quienes no la entregaron no podrán salir.")],
  [E("¿Qué haces si no puedes explicar con tus palabras lo que leíste?", "Releo la parte que no entendí", "Releer ayuda a comprender."),
   E("¿Dónde suelen estar las pistas para entender una oración difícil?", "En la oración anterior y la siguiente", "El contexto aclara el significado."),
   E("¿Qué hay que hacer después de releer?", "Contar con mis palabras lo que entendí", "Así compruebo si comprendí.")],
  ("Lee este texto: «Aunque llovió toda la noche, el partido se jugó porque la cancha tiene drenaje y el agua escurre rápido.» Responde: 1) ¿Por qué se pudo jugar? 2) ¿Qué palabra muestra algo inesperado? 3) Explica con tus palabras qué significa «escurre» usando las pistas del texto.", "1) Porque la cancha tiene drenaje. 2) «Aunque». 3) «Escurre» significa que el agua se va del lugar y no se queda en la cancha.", ["responde las preguntas con el texto", "usa pistas para explicar la palabra", "cuenta lo leído con sus palabras"], ["tres respuestas escritas"], ["responder sin releer", "copiar el texto sin explicar"], "Relee tu explicación de «escurre»: ¿se entendería sin ver el texto?"),
  "Cuando leas algo que no entiendas, anota qué parte releíste y qué pista te ayudó.",
  "Busca en un texto una oración con «aunque» o «porque» y explícala con tus palabras.")

L(OA2, 3,
  "Este cuaderno, lápiz y el texto escrito en esta clase.",
  "Aprenderé a formular preguntas sobre lo que leo y a responderlas, distinguiendo las que se responden con el texto de las que necesitan que yo piense más allá.",
  ["Releo cuando no entiendo.", "Escribo preguntas con ¿ y ?."],
  ["Hacerse preguntas mientras se lee mejora la comprensión. Algunas preguntas son literales: su respuesta está escrita en el texto, como «¿Dónde suelen vivir los cóndores?». Para responderlas, buscas la información y la copias o la dices con otras palabras.",
   "Otras son inferenciales: la respuesta no está escrita, pero puedes deducirla uniendo pistas del texto y lo que sabes. Por ejemplo, «¿Por qué ahorrar energía ayuda a recorrer grandes distancias?» Y hay preguntas que el texto no puede responder, porque piden datos que no trae; para ellas necesitas otra fuente.",
   "Las preguntas empiezan con palabras como qué, quién, dónde, cuándo, cómo y por qué. «Por qué» pide una causa o razón. Después de formular una pregunta, vuelve al texto, busca la respuesta y comprueba que realmente la contesta."],
  [("pregunta literal", "pregunta cuya respuesta está escrita en el texto"), ("pregunta inferencial", "pregunta cuya respuesta se deduce con pistas del texto"), ("causa", "la razón por la que ocurre algo"), ("fuente", "lugar de donde se obtiene información")],
  [("Responder una pregunta literal", f"Texto: «{CONDOR}» ¿Dónde suelen vivir los cóndores?", ["Busco «viven» en el texto.", "Encuentro: «suelen vivir en la cordillera».", "Respondo con esa información."], "En la cordillera"),
   ("Reconocer una pregunta sin respuesta en el texto", "¿El texto de los cóndores responde la pregunta «¿Cuántos años viven los cóndores?»?", ["Reviso las tres oraciones.", "Ninguna habla de la edad.", "El texto no la responde; hay que buscar otra fuente."], "No, falta esa información")],
  [("Responder una pregunta con lo que uno cree, sin mirar el texto.", "Se confunde saber con comprender el texto.", "Vuelve al texto y comprueba la respuesta."), ("Escribir una pregunta sin ¿ de apertura.", "Se olvida el signo inicial.", "Escribe ¿ al comienzo y ? al final.")],
  ([E(CONDOR + " La respuesta a «¿Dónde viven los cóndores?» está escrita en el texto. ¿Es una pregunta literal o inferencial?", "Literal", "Su respuesta se encuentra directamente en el texto."),
    E("¿Cuál es una pregunta: «Los cóndores vuelan.» o «¿Cómo se elevan los cóndores?»?", "«¿Cómo se elevan los cóndores?»", "Lleva signos de interrogación y pide un dato."),
    E("Una pregunta literal se responde con: (a) lo que está escrito en el texto o (b) con pura imaginación.", "(a)", "Su respuesta está en el texto.")],
   [E(CONDOR + " «¿Qué usan los cóndores para elevarse?» ¿Es literal o inferencial?", "Literal", "El texto dice que usan corrientes de aire caliente."),
    E(CONDOR + " «¿Por qué ahorrar energía ayuda a recorrer grandes distancias?» ¿Se responde copiando una frase o hay que deducirla?", "Hay que deducirla", "Es una pregunta inferencial."),
    E(CONDOR + " ¿Cuál NO se puede responder con el texto: (a) «¿Para qué usan las corrientes de aire?» o (b) «¿Cuántos años viven los cóndores?»?", "(b)", "El texto no dice la edad.")],
   [E("¿Cuál pregunta tiene como respuesta «ahorran energía y recorren grandes distancias»: (a) «¿Dónde viven los cóndores?» o (b) «¿Qué ganan los cóndores al usar las corrientes de aire?»?", "(b)", "La respuesta habla de lo que ganan."),
    E(CONDOR + " Responde con el texto: ¿Dónde descansan los cóndores?", "En las rocas altas de la cordillera", "El texto dice que allí hay rocas altas para descansar."),
    E("Escribe con signos: «Qué comen los cóndores».", "¿Qué comen los cóndores?", "Es una pregunta: lleva ¿ y ?.")],
   [E(CONDOR + " Ana pregunta «¿Por qué los cóndores no necesitan aletear mucho?» ¿Se puede responder con el texto?", "Sí", "Porque usan corrientes de aire caliente para elevarse."),
    E(CONDOR + " Beto pregunta «¿Cuántos cóndores hay en Chile?» ¿Qué necesitas para responder: el texto o otra fuente?", "Otra fuente", "El texto no entrega esa cifra.")],
   [E(CONDOR + " Según el texto, si no hubiera corrientes de aire caliente, ¿qué le costaría a un cóndor?", "Elevarse sin aletear", "El texto dice que las usa para eso."),
    E("¿Qué palabra de pregunta pide una causa: dónde, por qué o cuándo?", "Por qué", "Pregunta la razón de algo.")]),
  [E("Un cartel dice: «La biblioteca abrirá desde el lunes, de 9 a 13 horas.» ¿Cuál pregunta tiene como respuesta «de 9 a 13 horas»: (a) «¿Dónde está la biblioteca?» o (b) «¿En qué horario abrirá la biblioteca?»?", "(b)", "Pregunta por el horario.")],
  [E("¿Qué es una pregunta literal?", "Una cuya respuesta está escrita en el texto", "Se responde buscando en el texto."),
   E("¿Qué es una pregunta inferencial?", "Una cuya respuesta se deduce con pistas", "La respuesta no está escrita palabra por palabra."),
   E("¿Qué haces si el texto no puede responder tu pregunta?", "Busco otra fuente", "El texto no trae esa información.")],
  (f"Lee este texto: «{CONDOR}» Escribe tres preguntas: una literal, una inferencial y otra que el texto no pueda responder. Luego responde las dos primeras y explica por qué la tercera no se puede responder con el texto.", "Literal: ¿Qué usan para elevarse? Respuesta: corrientes de aire caliente. Inferencial: ¿Por qué no se cansan tanto? Respuesta: porque no aletean mucho. Sin respuesta: ¿Cuánto pesa un cóndor? El texto no dice el peso.", ["escribe tres preguntas con signos", "responde la literal con el texto", "explica por qué una no se puede responder"], ["tres preguntas y respuestas"], ["preguntas sin ¿", "responder sin mirar el texto"], "Pide a otra persona que clasifique tus preguntas y compara con tu clasificación."),
  "Lee una noticia y escribe dos preguntas literales y una inferencial sobre ella.",
  "Elige un texto de otra asignatura y escribe una pregunta que solo se pueda responder con otra fuente.")

L(OA2, 4,
  "Este cuaderno, lápiz y el texto escrito en esta clase.",
  "Aprenderé a identificar las ideas más importantes de un texto según para qué lo leo, es decir, según mi propósito.",
  ["Releo y formulo preguntas.", "Distingo un dato de una opinión."],
  ["Un texto tiene muchas informaciones, pero no todas pesan lo mismo. Las ideas más importantes son las que no pueden faltar para entender el tema según lo que necesitas. Los detalles aportan datos extra, pero se pueden dejar de lado si no sirven a tu propósito.",
   "El propósito del lector es para qué lee: para saber cuándo es un evento, para estudiar, para contar algo a alguien. Si el propósito cambia, lo importante también cambia. Un mismo texto puede dar ideas principales distintas según lo que busques.",
   "Para elegir lo importante, pregúntate: ¿qué necesito saber? Marca esas ideas con lápiz y deja sin marcar los detalles. Después, comprueba si con lo marcado podrías cumplir tu propósito sin volver a leer todo."],
  [("idea principal", "lo más importante que dice un texto según lo que se busca"), ("detalle", "dato que complementa, pero no es esencial"), ("propósito del lector", "para qué se lee un texto"), ("subrayar", "marcar lo importante con una línea")],
  [("Cambiar de propósito", f"Texto: «{FERIA}» Quieres saber cuándo ir a la feria. ¿Qué idea es la más importante?", ["Mi propósito es saber cuándo ir.", "Busco día y horario.", "La idea clave es: sábado 12, de 10 a 18 horas."], "Sábado 12, de 10 a 18 horas"),
   ("Otro propósito, otras ideas", "Con el mismo texto, quieres contarle a una amiga qué actividades habrá. ¿Cuáles son las ideas importantes?", ["Mi propósito es contar actividades.", "Busco lo que habrá.", "Son: cuentacuentos para niños y taller de poesía a las 15 horas."], "Cuentacuentos y taller de poesía")],
  [("Subrayar casi todo el texto.", "Cuesta decidir qué importa.", "Pregunta qué necesitas según tu propósito y marca solo eso."), ("Usar siempre las mismas ideas aunque el propósito cambie.", "Se cree que lo importante es fijo.", "Revisa tu propósito antes de marcar.")],
  ([E("¿Qué es la idea principal: lo más importante para tu propósito o un detalle?", "Lo más importante para tu propósito", "Es la información que no puede faltar."),
    E(FERIA + " Según el texto de la feria, ¿a qué hora es el taller de poesía?", "A las 15 horas", "Lo dice la segunda oración."),
    E(FERIA + " Según el texto, ¿cuánto cuesta la entrada?", "Nada; es gratuita", "La tercera oración lo dice.")],
   [E("Quieres saber cuándo ir. ¿Qué idea es más importante: «sábado 12, de 10 a 18 horas» o «llevar una bolsa»?", "«sábado 12, de 10 a 18 horas»", "Responde al propósito de saber cuándo ir."),
    E("Quieres contar a una amiga qué actividades habrá. ¿Cuáles son importantes?", "Cuentacuentos y taller de poesía", "Son las actividades que menciona el texto."),
    E("Si cambia tu propósito, ¿puede cambiar lo importante del mismo texto?", "Sí", "Importa lo que sirve a lo que buscas.")],
   [arith("La feria abre de 10 a 18 horas. ¿Cuántas horas está abierta?", "18-10", "Se restan la hora de apertura de la de cierre."),
    E(FERIA + " ¿Cuántas actividades distintas menciona el texto de la feria?", "2", "Cuentacuentos y taller de poesía."),
    E(FERIA + " Quieres saber si debes pagar. ¿Qué oración lees con más atención: «La entrada es gratuita.» o «Habrá cuentacuentos para niños.»?", "«La entrada es gratuita.»", "Responde si hay que pagar.")],
   [E(FERIA + " Ana lee la feria para saber qué debe llevar; Beto, para saber el horario. ¿Qué dato necesita Ana?", "Una bolsa para guardar los libros", "Es lo que piden los organizadores."),
    E("Alguien resume «Hay una feria». ¿Sirve para decidir a qué hora llegar?", "No", "No trae el horario.")],
   [arith("Si llegas al taller a las 15 horas y te quedas hasta el cierre (18 horas), ¿cuántas horas estarás en la feria?", "18-15", "Se restan 15 de 18."),
    E("Para un afiche con poco espacio, ¿qué resumen sirve mejor: (a) «Feria del Libro: sábado 12, de 10 a 18 horas, en la plaza. Entrada gratuita.» o (b) «Los organizadores piden bolsas.»?", "(a)", "Reúne las ideas centrales.")]),
  [E("Una nota dice: «El paseo es el viernes. Salimos a las 8:30. Lleven colación y gorro. Si llueve, se suspende.» Si tu propósito es saber qué llevar, ¿cuál es la idea clave?", "Colación y gorro", "Es lo que hay que llevar.")],
  [E("¿Qué es el propósito del lector?", "Para qué lee un texto", "Determina qué ideas importan."),
   E("¿Qué se hace con los detalles que no sirven a tu propósito?", "Se dejan de lado", "No son esenciales para lo que buscas."),
   E("Si cambias el propósito, ¿puedes cambiar las ideas que subrayas?", "Sí", "Lo importante depende de lo que buscas.")],
  (f"Lee este texto: «{FERIA}» Haz dos listas: 1) ideas importantes si quieres decidir si vas con tu familia a la feria; 2) ideas importantes si debes preparar la bolsa y la colación. Explica por qué las listas son distintas.", "1) Sábado 12, de 10 a 18 horas, plaza, entrada gratuita. 2) Llevar una bolsa; las demás ideas importan menos. Las listas cambian porque el propósito cambia.", ["escribe dos listas", "las listas responden a cada propósito", "explica por qué son distintas"], ["dos listas", "explicación"], ["copiar todo el texto", "no cambiar la lista según el propósito"], "Compara tus listas con las de otra persona y revisa si responden a los propósitos."),
  "Lee un texto breve de tu casa o de la escuela y subraya solo lo que necesitas para un propósito.",
  "Escribe un mismo texto de tres líneas con dos propósitos distintos y marca ideas diferentes en cada caso.")

L(OA2, 5,
  "Este cuaderno, lápiz y el texto escrito en esta clase.",
  "Aprenderé a organizar la información de un texto en un esquema o en un mapa conceptual para entenderla y recordarla.",
  ["Identifico ideas importantes.", "Ordeno pasos de un proceso."],
  ["Un esquema ordena la información con recuadros y flechas. Sirve especialmente para procesos, donde unos pasos siguen a otros: cada recuadro lleva un paso y la flecha muestra cuál viene después. Así ves el texto completo de un vistazo.",
   "Un mapa conceptual relaciona conceptos. Pones el tema central en un recuadro, de él salen líneas hacia otros conceptos y sobre cada línea escribes una palabra de enlace, como «forma» o «se convierte en». Si lees la línea completa, obtienes una oración.",
   "Para hacer uno, primero lee y marca las ideas importantes. Luego decide qué organizador te sirve: esquema de flechas si hay pasos; mapa si hay un tema con partes. Usa pocas palabras en cada recuadro y revisa que el orden sea el del texto."],
  [("esquema", "organizador con recuadros y flechas que ordena ideas"), ("mapa conceptual", "organizador que une conceptos con líneas y palabras de enlace"), ("palabra de enlace", "palabra sobre una línea que une dos conceptos"), ("proceso", "serie de pasos que ocurren uno después de otro")],
  [("Armar un esquema", f"Texto: «{AGUA}» Ordena los pasos.", ["Primero: el agua se calienta y sube como vapor.", "Después: el vapor se enfría y forma nubes.", "Al final: cae como lluvia o nieve."], "Vapor → nubes → lluvia o nieve"),
   ("Una palabra de enlace", "En un mapa, «vapor» se conecta con «nubes». ¿Qué palabra de enlace sirve: «se enfría y forma» o «es de color»?", ["Leo la línea completa como oración.", "«El vapor se enfría y forma nubes» tiene sentido.", "La otra no explica la relación."], "«se enfría y forma»")],
  [("Escribir frases largas dentro de cada recuadro.", "Se copia el texto completo.", "Usa pocas palabras clave."), ("Poner los pasos en un orden distinto al del texto.", "Se arma sin releer.", "Revisa el orden con el texto.")],
  ([E("En un esquema, ¿la flecha entre dos recuadros indica que un paso sigue al otro o que son lo mismo?", "Que un paso sigue al otro", "La flecha marca el orden."),
    E(AGUA + " Según el texto del agua, ¿qué ocurre primero?", "El agua sube al aire como vapor", "Es lo primero que dice el texto."),
    E(AGUA + " Según el texto, ¿cómo vuelve el agua al mar y a los ríos?", "Cae como lluvia o nieve", "Es el último paso.")],
   [E("Ordena con letras: (a) se forman nubes, (b) el agua sube como vapor, (c) cae lluvia o nieve.", "b, a, c", "Es el orden del texto."),
    E("¿Para qué sirven las palabras de enlace de un mapa conceptual?", "Para unir conceptos formando una oración", "Explican la relación entre dos conceptos."),
    E("Entre «vapor» y «nubes», ¿qué enlace sirve: «se enfría y forma» o «es de color»?", "«se enfría y forma»", "Lee como «el vapor se enfría y forma nubes».")],
   [E("Completa el esquema: [El sol calienta el agua] → [Sube como ___] → [Forma nubes] → [Cae lluvia o nieve].", "Vapor", "El texto dice que sube como vapor."),
    E("Cuenta los recuadros: [El sol calienta el agua] → [Sube como vapor] → [Forma nubes] → [Cae lluvia o nieve]. ¿Cuántos son?", "4", "Hay cuatro pasos."),
    E("En un mapa conceptual, quieres unir «nubes» con «lluvia o nieve». ¿Qué enlace sirve: (a) «dejan caer» o (b) «están en»?", "(a)", "«Las nubes dejan caer lluvia o nieve» tiene sentido; la otra opción no.")],
   [E("Ana ordena: nubes, vapor, lluvia. ¿Está bien?", "No", "Primero el agua sube como vapor."),
    E("¿Por qué un esquema ayuda a estudiar: porque muestra de un vistazo cómo se relacionan las ideas o porque reemplaza leer?", "Porque muestra de un vistazo cómo se relacionan las ideas", "No reemplaza la lectura; la resume.")],
   [E(AGUA + " Según el texto, ¿adónde vuelve el agua que cae?", "A los ríos y al mar", "Termina donde empezó."),
    E("Se llama «ciclo» del agua porque: (a) el proceso se repite o (b) el agua es redonda.", "(a)", "El agua que vuelve al mar puede volver a subir.")]),
  [E("Debes estudiar un texto con tres pasos que se suceden. ¿Qué organizador usas: una lista de pasos con flechas o un dibujo de tu mascota?", "Una lista de pasos con flechas", "Muestra el orden de los pasos.")],
  [E("¿Qué muestra la flecha en un esquema de proceso?", "Qué paso sigue", "Marca el orden."),
   E("¿Qué escribimos sobre las líneas de un mapa conceptual?", "Palabras de enlace", "Unen los conceptos."),
   E("¿Cuántas palabras conviene poner en cada recuadro: pocas o todo el párrafo?", "Pocas", "Se anotan solo palabras clave.")],
  (f"Lee este texto: «{GLACIAR}» Haz un esquema con flechas que muestre cómo se forma un glaciar y un mapa conceptual con «glaciar» al centro y al menos dos palabras de enlace.", "Esquema: [Cae más nieve de la que se derrite] → [La nieve se aprieta] → [Se convierte en hielo]. Mapa: glaciar —es una masa de→ hielo; glaciar —se mueve→ muy despacio.", ["esquema con orden correcto", "mapa con concepto central y enlaces", "pocas palabras en cada recuadro"], ["un esquema", "un mapa conceptual"], ["frases largas en los recuadros", "orden equivocado"], "Lee cada línea del mapa como una oración y comprueba que tenga sentido."),
  "Elige un texto de Ciencias o Historia y arma un esquema de lo más importante.",
  "Convierte el esquema del agua en un mapa conceptual con tres palabras de enlace.")

L(OA2, 6,
  "Este cuaderno, lápiz y el texto escrito en esta clase.",
  "Aprenderé a elegir y combinar las estrategias de comprensión que mejor sirven en cada situación y a revisar si comprendí.",
  ["Relaciono, releo, pregunto, busco lo importante y organizo."],
  ["Un lector competente no usa siempre la misma estrategia: elige la adecuada. Si no entiende una oración, relee. Si quiere recordar un proceso, hace un esquema. Si quiere profundizar, se pregunta y responde. Si el texto trata algo conocido, relaciona con sus experiencias.",
   "Muchas veces conviene combinar estrategias. Antes de leer, relacionas con lo que sabes. Durante la lectura, te preguntas y relees lo difícil. Al terminar, subrayas las ideas importantes y las organizas en un esquema. Cada paso cuida un aspecto distinto de la comprensión.",
   "Para comprobar si comprendiste, intenta explicar con tus palabras el texto y responder tus preguntas sin mirar. Si no puedes, vuelve atrás y prueba otra estrategia. Aprender a decidir qué estrategia usar es una parte importante de leer bien."],
  [("estrategia", "forma de actuar para lograr algo, como comprender un texto"), ("combinar", "usar dos o más cosas juntas"), ("monitorear", "darse cuenta de si se está comprendiendo"), ("explicar con tus palabras", "decir lo leído sin copiar el texto")],
  [("Elegir una estrategia", f"Texto: «{GLACIAR}» Quieres recordar el proceso de formación del glaciar para una prueba. ¿Qué estrategia usas?", ["El texto describe pasos que se suceden.", "Un esquema con flechas muestra el orden.", "Dibujo: nieve → se aprieta → hielo."], "Hacer un esquema"),
   ("Combinar estrategias", "No entiendes «masas de hielo» y luego quieres saber más. ¿Qué estrategias combinas?", ["Releo la oración buscando pistas: «enormes masas» son grandes cantidades.", "Luego me pregunto: ¿cómo se mueven?", "Busco la respuesta: «muy despacio»."], "Releer y luego preguntar")],
  [("Usar siempre la misma estrategia para todo.", "Se aprendió una y se repite.", "Elige según el problema que enfrentas."), ("Creer que ya comprendiste sin comprobarlo.", "Se confunde terminar con entender.", "Explica con tus palabras y responde preguntas.")],
  ([E("No entiendes una oración. ¿Qué estrategia usas?", "Releer", "Volver a leer ayuda a aclarar."),
    E("Antes de leer, ¿qué estrategia recuerda lo que ya sabes?", "Relacionar con lo que sé", "Activa los conocimientos previos."),
    E("¿Cuál es una estrategia de comprensión: releer o adivinar sin leer?", "Releer", "Releer es una estrategia; adivinar sin leer no.")],
   [E(GLACIAR + " Según el texto del glaciar, ¿dónde se forman los glaciares?", "Donde cae más nieve de la que se derrite", "Lo dice la segunda oración."),
    E(GLACIAR + " ¿Qué le pasa a la nieve con el tiempo?", "Se aprieta y se convierte en hielo", "Lo dice la última oración."),
    E("Quieres recordar el proceso (nieve → se aprieta → hielo) para una prueba. ¿Qué estrategia sirve más: hacer un esquema o releer solo una vez?", "Hacer un esquema", "Muestra el orden del proceso.")],
   [E(GLACIAR + " ¿Cuál es una pregunta literal sobre el texto: (a) «¿Cómo se mueven los glaciares?» o (b) «¿Cuántos glaciares hay en el mundo?»?", "(a)", "El texto dice que se mueven muy despacio."),
    E(GLACIAR + " Si tu propósito es explicar qué es un glaciar, ¿qué idea es la más importante?", "Son enormes masas de hielo que se mueven muy despacio", "Define lo que es un glaciar."),
    E("Ordena con letras: (a) se convierte en hielo, (b) cae nieve que no se derrite, (c) la nieve se aprieta.", "b, c, a", "Es el orden del proceso en el texto.")],
   [E("Tomás leyó que la nieve «se aprieta» y pensó que se derretía. ¿Qué estrategia corrige su error?", "Releer", "Al releer ve que se aprieta y se vuelve hielo."),
    E("Una niña usa tres estrategias (relaciona, relee y hace un esquema); otro lee una sola vez. ¿Quién probablemente comprende mejor?", "La niña que usa tres estrategias", "Cada estrategia cuida un aspecto de la comprensión.")],
   [E("Dos situaciones: «no sé qué significa “masas”» y «no recuerdo los pasos del proceso». ¿Qué estrategia usas en cada una, en ese orden?", "Releer con pistas y hacer un esquema", "Una aclara la palabra; la otra organiza los pasos."),
    E(GLACIAR + " Según el texto, ¿puede formarse un glaciar donde la nieve se derrite más de lo que cae?", "No", "Se forman donde cae más nieve de la que se derrite.")]),
  [E("Al leer las reglas de un juego de mesa no entiendes una. ¿Qué estrategia usas primero?", "Releer la regla", "Volver a leerla permite aclarar la duda.")],
  [E("¿Siempre sirve la misma estrategia?", "No", "Se elige según lo que se necesita."),
   E("¿Cómo compruebas que comprendiste?", "Explico con mis palabras y respondo preguntas", "Así muestras si entendiste."),
   E("Si no puedes explicar lo leído, ¿qué haces?", "Pruebo otra estrategia", "Así vuelvo a intentar entenderlo.")],
  (f"Lee este texto: «{GLACIAR}» Usa al menos tres estrategias: escribe una conexión con lo que sabes, una pregunta con su respuesta y un esquema breve. Al final explica con tus palabras de qué trata el texto.", "Conexión: sé que la nieve se aprieta cuando la pisamos. Pregunta: ¿cómo se mueven? Respuesta: muy despacio. Esquema: nieve → se aprieta → hielo. Trata de cómo se forman los glaciares.", ["usa tres estrategias distintas", "responde la pregunta con el texto", "explica con sus palabras"], ["conexión", "pregunta y respuesta", "esquema", "explicación"], ["repetir la misma estrategia", "copiar el texto"], "Marca qué estrategia te ayudó más y por qué."),
  "Al leer en cualquier asignatura, anota qué estrategia usaste cada vez que algo no se entendía.",
  "Explica a otra persona cómo elegir una estrategia según el problema que se tenga al leer.")
